import org.openqa.selenium.By;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import org.testng.annotations.Test;

public class ProductTypeMasterTest {
    @Test
    public void testAddProductType() {
        WebDriver driver = new ChromeDriver();
        driver.get("https://gc-dev.centralindia.cloudapp.azure.com/ambica/auth/login");
        driver.findElement(By.xpath("//button[contains(text(),'Master Data')]")).click();
        driver.findElement(By.linkText("Product Type Master")).click();

        driver.findElement(By.xpath("//button[contains(text(),'Add Product Type')]")).click();
        driver.findElement(By.id("productTypeName")).sendKeys("Selenium Type");
        driver.findElement(By.id("description")).sendKeys("Automated description");
        driver.findElement(By.xpath("//button[contains(text(),'Submit')]")).click();
        driver.quit();
    }
}
